(function () {
  'use strict';
  const chunkSet = {"title":"Advanced Punctuation","topic":"Punctuation","questions":[{"id":"punctuation-advanced-punctuation-q0151","version":5,"contentHash":"sha256:b71a8817f2ca946ac9e69d81f338f1a2cf927e4a2ee84cb9233fc29e601aa116","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a semicolon correctly?","choices":["The storm; ended the teams returned.","The storm ended; the teams returned to the field.","The storm ended; because the field.","The; storm ended."],"correct":1,"studyAid":{"definition":"A semicolon connects two complete, independent sentences that are closely related in meaning.","example":"I love to read; books are my favorite hobby. The sun set; the stars began to twinkle.","strategyClue":"Check if there is a complete sentence on both sides of the semicolon. If you can put a period in place of the semicolon and both halves still make perfect sense alone, the semicolon is likely placed correctly.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The storm ended; the teams returned to the field. A semicolon is used to join two independent clauses that are closely related in thought, acting like a soft period that links two complete sentences together.","incorrect":[{"choice":"The storm; ended the teams returned.","category":"misplaced semicolon","reason":"Placing the semicolon after 'storm' breaks the subject 'The storm' from its verb 'ended', which makes the sentence confusing and grammatically broken."},"",{"choice":"The storm ended; because the field.","category":"semicolon with conjunction","reason":"You cannot use a semicolon before 'because' here because 'because the field' is not an independent clause; it is a dependent fragment."},{"choice":"The; storm ended.","category":"punctuation error","reason":"A semicolon should never be placed between an article ('The') and a noun ('storm'). This separates words that belong together."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":151,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0152","version":5,"contentHash":"sha256:0229d431cae7487bb651dfa92a7bcd2b5dc2cff967c8c8b667dad93ebf335afa","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a colon correctly before a list?","choices":["Bring: three supplies pencils.","Bring three: supplies pencils, paper, and glue.","Bring three supplies: pencils, paper, and glue.","Bring three supplies pencils: paper."],"correct":2,"studyAid":{"definition":"A colon is used to introduce a list after a complete sentence. It acts like a gatekeeper, signaling that the information following it relates directly to the words before it.","example":"I need these items: boots, a coat, and a hat. / She studied three subjects: math, science, and history.","strategyClue":"Check if the words before the colon form a complete sentence. If you can stop reading and understand the thought before the colon, you have likely placed it correctly to introduce your list.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Bring three supplies: pencils, paper, and glue. A colon is used to introduce a list after a complete introductory sentence or clause that sets up what is to follow.","incorrect":[{"choice":"Bring: three supplies pencils.","category":"incorrect colon placement","reason":"Placing the colon after the verb 'Bring' interrupts the flow of the sentence. A colon should only be used after a full, independent thought that introduces a list."},{"choice":"Bring three: supplies pencils, paper, and glue.","category":"incorrect colon placement","reason":"The phrase 'Bring three' is not a complete sentence, and the colon is placed in the middle of the list items. The colon should come after the entire phrase that introduces the list."},"",{"choice":"Bring three supplies pencils: paper.","category":"incorrect colon placement","reason":"The colon is placed way too late in the sentence. It needs to appear immediately after the word 'supplies' to signal that a list is about to begin."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":152,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0153","version":5,"contentHash":"sha256:5fda3a954672401b82419f3ba0309f9962e4e7fdac5a0387409aa266e4ac9e6e","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses parentheses correctly?","choices":["The field trip originally planned for May) moved.","The field trip originally) planned for May moved.","The field trip (originally planned for May moved.","The field trip (originally planned for May) moved to June."],"correct":3,"studyAid":{"definition":"Parentheses are used to set off extra information that provides more detail but is not strictly necessary for the sentence to make sense.","example":"My dog (a golden retriever) loves to swim. The store is closed (it is a holiday).","strategyClue":"Cover the words inside the parentheses with your finger. If the remaining words still form a complete, grammatically correct sentence, you have correctly identified the extra information that needs to be enclosed.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The field trip (originally planned for May) moved to June. Parentheses must always work in pairs to enclose extra or clarifying information that is not essential to the main meaning of the sentence.","incorrect":[{"choice":"The field trip originally planned for May) moved.","category":"missing opening parenthesis","reason":"This sentence has a closing parenthesis but no opening one. Parentheses must come in pairs to fully enclose the extra information."},{"choice":"The field trip originally) planned for May moved.","category":"misplaced parentheses","reason":"The parentheses are placed in the middle of the phrase, breaking it apart incorrectly. The entire extra detail must be inside both brackets."},{"choice":"The field trip (originally planned for May moved.","category":"missing closing parenthesis","reason":"This sentence has an opening parenthesis but is missing the closing one. Without it, the sentence feels incomplete and confusing to the reader."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":153,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0154","version":5,"contentHash":"sha256:3f141286f7cac2dc0427124537c5dfc6d89e869ec8b8d521a1f7f7287b538416","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a comma after an introductory phrase?","choices":["After the bell rang, students lined up.","After the bell rang students lined up.","After, the bell rang students lined up.","After the bell, rang students lined up."],"correct":0,"studyAid":{"definition":"An introductory phrase comes at the start of a sentence and sets the scene; a comma should be placed immediately after this phrase to signal the start of the main clause.","example":"Before the show started, we found our seats. Because it was raining, we stayed inside.","strategyClue":"Read the sentence out loud and listen for a natural pause after the opening thought. That pause marks exactly where the comma should be placed before the main action begins.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After the bell rang, students lined up. Introductory phrases provide context and are followed by a comma to separate them from the main part of the sentence.","incorrect":["",{"choice":"After the bell rang students lined up.","category":"missing comma","reason":"This sentence fails to use a comma after the introductory phrase 'After the bell rang,' which makes the sentence harder to read and grammatically incomplete."},{"choice":"After, the bell rang students lined up.","category":"misplaced comma","reason":"The comma is placed after the single word 'After' instead of after the entire introductory clause, which breaks the flow of the sentence incorrectly."},{"choice":"After the bell, rang students lined up.","category":"misplaced comma","reason":"The comma is placed in the middle of the introductory phrase, which incorrectly splits the noun 'bell' from the verb 'rang'."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":154,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0155","version":5,"contentHash":"sha256:1f0ff126e33ab0c0aae9860aca8da225db267c44022218f6fd6e27bf811f35e4","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a hyphen correctly?","choices":["The well known-author visited.","The well-known author visited our school.","The well known author-visited.","The wellknown author visited."],"correct":1,"studyAid":{"definition":"Use a hyphen to join two words into a single adjective when they come right before the noun they describe.","example":"a high-speed train, an ice-cold drink, a well-known story","strategyClue":"Identify the two words working as a team to describe the noun. Check if those two words come immediately before that noun, and if so, place the hyphen between them.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The well-known author visited our school. A hyphen is used to join two words that act as a single adjective before a noun. 'Well-known' works together to describe the author.","incorrect":[{"choice":"The well known-author visited.","category":"Incorrect hyphen placement","reason":"The hyphen is placed after the wrong word. A hyphen should connect the two descriptive words before the noun, not connect one word to the noun itself."},"",{"choice":"The well known author-visited.","category":"Misplaced hyphen","reason":"Hyphens connect compound modifiers before a noun. Connecting 'author' to 'visited' does not make sense because those are not a compound adjective."},{"choice":"The wellknown author visited.","category":"Missing hyphen","reason":"The word 'well' needs to be connected to 'known' with a hyphen. Without it, the sentence looks like one made-up word, which is not standard English."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":155,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0156","version":5,"contentHash":"sha256:c3d12cf7a5c99adf7c742a10bbb4a9014d01fdff9f15561cf27df3497e32ca87","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a dash correctly?","choices":["- I opened the box and.","I opened - the box and gasped at.","I opened the box - and gasped at the surprise inside.","I opened the - box - and."],"correct":2,"studyAid":{"definition":"A dash is a punctuation mark used to indicate a sudden change in thought, an interruption, or to add extra emphasis to a specific part of a sentence.","example":"I was hungry—really hungry—for pizza. She ran to the door—but nobody was there.","strategyClue":"Read each sentence aloud. Look for the spot where your voice would naturally pause or hesitate to add a dramatic effect. Place the dash where that mental break occurs.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: I opened the box - and gasped at the surprise inside. A dash is used to show a sudden break in thought or to add emphasis to an extra phrase in a sentence.","incorrect":[{"choice":"- I opened the box and.","category":"incorrect dash placement","reason":"Starting a sentence with a dash is incorrect. Dashes are meant to connect ideas within a sentence, not to begin one."},{"choice":"I opened - the box and gasped at.","category":"incorrect dash placement","reason":"Placing a dash between a verb and its object breaks the natural flow of the sentence. Dashes should separate distinct thoughts, not individual words."},"",{"choice":"I opened the - box - and.","category":"excessive dash usage","reason":"Using two dashes in a row here creates a fragmented look that interrupts the main action unnecessarily. A single dash is sufficient to create the intended pause."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":156,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0157","version":5,"contentHash":"sha256:06448f4de33ab24810d9f03aa24750aaafb9f2abcccef8f12ab31cfee634934f","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses quotation marks for a title correctly?","choices":["We read The Marble Champ in \"class.\"","We read The Marble Champ\" in class.","We read \"The Marble Champ in class.","We read \"The Marble Champ\" in class."],"correct":3,"studyAid":{"definition":"Quotation marks are used to set off the titles of shorter works, such as short stories, poems, songs, or essays. Place the opening mark before the first word and the closing mark after the very last word of the title.","example":"I memorized \"The Road Not Taken\" for class. She sang \"Twinkle, Twinkle, Little Star\" perfectly.","strategyClue":"Identify the specific title of the story in the sentence. Locate the first and last words of that title, then ensure both ends are hugged by quotation marks.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: We read \"The Marble Champ\" in class. Titles of short works like stories, poems, or articles should be enclosed in quotation marks, starting before the first word and ending after the last word of the title.","incorrect":[{"choice":"We read The Marble Champ in \"class.\"","category":"misplaced quotation marks","reason":"Quotation marks are used for titles, not for regular words like 'class'. The title of the story is 'The Marble Champ', so the marks belong there instead."},{"choice":"We read The Marble Champ\" in class.","category":"missing opening quotation mark","reason":"Quotation marks work in pairs. Since there is no mark before 'The', the reader does not know where the title begins."},{"choice":"We read \"The Marble Champ in class.","category":"missing closing quotation mark","reason":"You must close the quotation marks after the end of the title. Leaving the mark off at the end makes the sentence look incomplete."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":157,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0158","version":4,"contentHash":"sha256:f97bd154f1042f3204e6931c5e03f6d434c3834c84b9beaca369bdf656eae0c2","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a colon to show time?","choices":["Practice begins at 4:30.","Practice begins at 4;30.","Practice begins at 4,30.","Practice begins at 4.30."],"correct":0,"studyAid":{"definition":"A colon (:) is the punctuation mark used to separate hours from minutes when writing the time.","example":"Correct: 12:00, 7:15, 9:45; Incorrect: 7.15, 9,45","strategyClue":"Visualize how you see times displayed on a digital clock or a watch. The symbol that divides the hour from the minutes is the one you should choose.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Practice begins at 4:30. A colon is used as the standard separator between hours and minutes when writing the time of day.","incorrect":["",{"choice":"Practice begins at 4;30.","category":"semicolon misuse","reason":"A semicolon is used to join two related independent clauses, not to separate numbers in a time. You should use a colon instead."},{"choice":"Practice begins at 4,30.","category":"comma misuse","reason":"Commas are used to separate items in a list or clauses in a sentence. Using a comma here creates confusion between the hour and the minutes."},{"choice":"Practice begins at 4.30.","category":"period misuse","reason":"Periods are used to end sentences or denote decimals. Using a period for time can make the number look like a decimal fraction rather than a specific time of day."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":158,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0159","version":4,"contentHash":"sha256:cf6c8fa85509f287d1ebf8d01a4650990188e427fabbf20972d11b76439faaf6","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses commas around a direct address?","choices":["Maya please, pass the markers.","Maya, please pass the markers.","Maya please pass, the markers.","Maya please pass the markers."],"correct":1,"studyAid":{"definition":"When you speak directly to someone and use their name, set the name apart from the rest of the sentence using a comma.","example":"Correct: 'Sam, come here.' Incorrect: 'Sam come here.' / Correct: 'Are you ready, team?' Incorrect: 'Are you ready team?'","strategyClue":"Read the sentence aloud. Pause slightly after the name you are calling out. The location of that natural pause is exactly where the comma should be placed.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Maya, please pass the markers. A comma is required to separate the name of the person being spoken to (the direct address) from the rest of the command or statement.","incorrect":[{"choice":"Maya please, pass the markers.","category":"incorrect comma placement","reason":"Placing the comma after 'please' breaks up the verb phrase 'please pass', which shouldn't be separated. The comma belongs after the name being addressed."},"",{"choice":"Maya please pass, the markers.","category":"incorrect comma placement","reason":"This comma incorrectly splits the verb 'pass' from its object 'the markers'. Commas are used to set off the name, not to pause in the middle of a command."},{"choice":"Maya please pass the markers.","category":"missing direct address comma","reason":"When you address someone directly by name, you must use a comma to show that the name is separate from the sentence itself."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":159,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0160","version":5,"contentHash":"sha256:e316aa97337606851fa51218ca4b366de97fbaaa5880407eb42d6bed4f8cc62c","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a semicolon correctly?","choices":["The storm ended; because the field.","The storm; ended the teams returned.","The storm ended; the teams returned to the field.","The; storm ended."],"correct":2,"studyAid":{"definition":"A semicolon links two independent, closely related sentences into one. Think of it as a bridge connecting two complete thoughts.","example":"Correct: I love reading; books are amazing. Incorrect: I love; reading books.","strategyClue":"Read the parts on both sides of the semicolon separately. If both sides are complete sentences that make sense on their own, the semicolon is used correctly.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The storm ended; the teams returned to the field. A semicolon is used to join two independent clauses—sentences that could stand alone—when they are closely related in thought.","incorrect":[{"choice":"The storm ended; because the field.","category":"incorrect clause structure","reason":"A semicolon should connect two complete sentences. 'Because the field' is a dependent phrase, not a complete thought, so it cannot follow a semicolon."},{"choice":"The storm; ended the teams returned.","category":"misplaced semicolon","reason":"The semicolon must go between two full sentences. Splitting the subject 'The storm' from its verb 'ended' breaks the sentence apart incorrectly."},"",{"choice":"The; storm ended.","category":"interrupting subject noun","reason":"You should never put a semicolon between an article and a noun. It belongs only between two complete, related sentences."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":160,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0161","version":5,"contentHash":"sha256:44729785424321d555e00fa095d8c8e1b90605b6d00128a0775ec6f97d6a0d7c","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a colon correctly before a list?","choices":["Bring three supplies pencils: paper.","Bring three: supplies pencils, paper, and glue.","Bring: three supplies pencils.","Bring three supplies: pencils, paper, and glue."],"correct":3,"studyAid":{"definition":"A colon is used after a complete sentence to introduce a list of items that follow. It acts like a gatekeeper saying, 'Here comes the list!'","example":"Correct: You need three colors: red, blue, and green. Incorrect: You need: red, blue, and green colors.","strategyClue":"Identify the complete introductory phrase that sets up the list, then look for the sentence where the colon sits directly between that introduction and the list items.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Bring three supplies: pencils, paper, and glue. A colon should be placed after a complete independent clause that introduces a list of items.","incorrect":[{"choice":"Bring three supplies pencils: paper.","category":"misplaced colon","reason":"This choice places the colon in the middle of the list items instead of before the list begins. The colon must come after the introductory phrase that tells us a list is coming."},{"choice":"Bring three: supplies pencils, paper, and glue.","reason":"\"Bring three: supplies pencils, paper, and glue.\" does not put the colon after a complete setup before the list or explanation."},{"choice":"Bring: three supplies pencils.","category":"missing list structure","reason":"This choice uses a colon but does not actually present a list of three items as the sentence structure suggests. A colon requires a complete list to follow it."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":161,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0162","version":5,"contentHash":"sha256:9075048c7b26832e0c70bd43ecbc64ba2687c5294ab6c9f1e7b4998cce63fcc4","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses parentheses correctly?","choices":["The field trip (originally planned for May) moved to June.","The field trip originally) planned for May moved.","The field trip (originally planned for May moved.","The field trip originally planned for May) moved."],"correct":0,"studyAid":{"definition":"Parentheses are used in pairs to set off information that is extra, explanatory, or added as an aside to the main sentence.","example":"My dog (a golden retriever) loves to swim. We visited Paris (the capital of France) last summer.","strategyClue":"Identify the group of words that provides extra information. Check that a starting mark is placed immediately before that group and a closing mark is placed immediately after it.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The field trip (originally planned for May) moved to June. Parentheses must always come in pairs. Both an opening parenthesis '(' and a closing parenthesis ')' are required to enclose the extra information.","incorrect":["",{"choice":"The field trip originally) planned for May moved.","category":"missing opening parenthesis","reason":"This sentence has a closing parenthesis but is missing the opening one. A parenthesis cannot work alone; it needs its partner to start the side note."},{"choice":"The field trip (originally planned for May moved.","category":"missing closing parenthesis","reason":"This sentence has an opening parenthesis but never closes it. Always look for the 'end' of the extra thought and place a closing mark there."},{"choice":"The field trip originally planned for May) moved.","category":"missing opening parenthesis","reason":"Similar to the first option, this choice only includes the end of the pair. Parentheses must surround the entire added phrase."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":162,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0163","version":5,"contentHash":"sha256:da0062af7134954919f981173ca8a906808bb02ae65c9b02587b0317717ce226","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence uses a comma after an introductory phrase?","choices":["After the bell rang students lined up.","After the bell rang, students lined up.","After, the bell rang students lined up.","After the bell, rang students lined up."],"correct":1,"studyAid":{"definition":"An introductory phrase or clause introduces the main sentence and is usually followed by a comma to help the reader pause.","example":"Incorrect: While he was eating the dog barked. Correct: While he was eating, the dog barked.","strategyClue":"Read the sentence aloud. Pause naturally after the introductory part that describes when or where something happened; the comma should go exactly where you take that breath.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After the bell rang, students lined up. Introductory phrases or clauses often set the scene for the main action and should be separated from the rest of the sentence by a comma.","incorrect":[{"choice":"After the bell rang students lined up.","category":"missing introductory comma","reason":"This sentence lacks a comma after the introductory dependent clause 'After the bell rang.' Without the comma, it is hard to tell where the introduction ends and the main action begins."},"",{"choice":"After, the bell rang students lined up.","category":"misplaced comma","reason":"Placing the comma after the single word 'After' breaks the phrase apart. The comma must come after the entire introductory clause, not in the middle of it."},{"choice":"After the bell, rang students lined up.","category":"incorrect comma placement","reason":"Putting the comma after 'bell' splits the prepositional phrase incorrectly. The comma belongs at the end of the entire introductory group of words before the main subject 'students' begins."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":163,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0164","version":7,"contentHash":"sha256:f9d2a70fa71c1e28d3f2ade09cffc8042d4f142450acb177e6ca1bc28aaf3887","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence correctly punctuates dialogue?","choices":["Please close the door,\" said Omar.","\"Please close the door\" said Omar.","\"Please close the door,\" said Omar.","\"Please close the door, said Omar.\""],"correct":2,"studyAid":{"definition":"Dialogue must be enclosed in quotation marks, and a comma should be used to separate the spoken words from the rest of the sentence.","example":"\"Hello!\" she shouted. / He asked, \"Are you ready?\"","strategyClue":"Look for the spot where the spoken words end and the speaker's name begins. Place your punctuation mark inside the closing quotation mark at that exact transition point.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: \"Please close the door,\" said Omar. When a spoken sentence ends inside the quotation marks, you must place a comma inside the closing quotation marks before you identify the speaker.","incorrect":[{"choice":"Please close the door,\" said Omar.","category":"missing opening quotation","reason":"Every piece of dialogue needs a quotation mark at the beginning as well as the end to show exactly what words are being spoken."},{"choice":"\"Please close the door\" said Omar.","category":"missing comma punctuation","reason":"Dialogue should be separated from the speaker tag with a comma. You need a comma inside the closing quotation mark to connect the two parts of the sentence."},"",{"choice":"\"Please close the door, said Omar.\"","category":"incorrect quotation scope","reason":"The quotation marks should only surround the words spoken. Including the speaker's name inside the quotation marks suggests that the character actually said their own name."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":164,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0165","version":7,"contentHash":"sha256:3e046e95f6f476d1ca65f6c04a012c858eaea62d9e409ed2f9dac40ce0cfbc11","question":"Grade 5 Medium: Use the context to choose the best answer. Which sentence starts a new speaker correctly?","choices":["I found it, said June. Where was it, asked Luis.","\"I found it,\" said June. \"Where was it?\" June asked.","\"I found it, said June. Where was it?\" asked Luis.","\"I found it,\" said June. \"Where was it?\" asked Luis."],"correct":3,"studyAid":{"definition":"Direct dialogue uses quotation marks around the exact words spoken, and a comma, question mark, or exclamation point is placed inside the closing quotation mark.","example":"\"Hello!\" she said. \"Are you ready?\" he asked.","strategyClue":"Look at each sentence and ask, 'Are these words being spoken aloud?' If they are, draw a line around them; the quotation marks must go exactly at the start and end of that line.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: \"I found it,\" said June. \"Where was it?\" asked Luis. Each piece of dialogue must be enclosed in quotation marks, and the punctuation belongs inside the quotation marks.","incorrect":[{"choice":"I found it, said June. Where was it, asked Luis.","category":"missing quotation marks","reason":"Without quotation marks, it is impossible to tell which words are spoken aloud. You must place marks around the exact words the characters say."},{"choice":"\"I found it,\" said June. \"Where was it?\" June asked.","category":"repetitive subject usage","reason":"While this is punctuated correctly, the prompt asks to track the speakers correctly; changing the speaker's name in the second sentence confuses the flow of the conversation compared to the original setup."},{"choice":"\"I found it, said June. Where was it?\" asked Luis.","category":"incorrect quotation scope","reason":"The quotation marks should only enclose the spoken words. In this option, the closing quotation mark is placed too late, accidentally including the speaker tag 'said June' inside the dialogue."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":65,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":165,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0166","version":5,"contentHash":"sha256:a185f988fbc2fa1ba4dd5d3a6e525394deaf878ed8060bb871dc78ca4c182c46","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a semicolon correctly?","choices":["The storm ended; the teams returned to the field.","The storm; ended the teams returned.","The storm ended; because the field.","The; storm ended."],"correct":0,"studyAid":{"definition":"A semicolon joins two independent, complete sentences that are closely related without using a conjunction like 'and' or 'but'.","example":"I love to read; it is my favorite hobby. The sun set; the stars came out.","strategyClue":"Cover the semicolon with your finger and read the parts on both sides. If both parts are complete sentences that could stand alone as their own sentence, the semicolon is used correctly.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The storm ended; the teams returned to the field. A semicolon is used to join two complete, independent sentences that are closely related in thought.","incorrect":["",{"choice":"The storm; ended the teams returned.","category":"misplaced semicolon","reason":"Placing a semicolon between a subject and its verb breaks the sentence apart incorrectly. A semicolon should only connect two complete ideas."},{"choice":"The storm ended; because the field.","category":"semicolon with conjunction","reason":"You cannot use a semicolon before a dependent word like 'because' to link incomplete thoughts. A semicolon requires a full, independent sentence on both sides."},{"choice":"The; storm ended.","category":"misplaced semicolon","reason":"You should never put a semicolon between an article like 'The' and the noun it modifies. The semicolon is for connecting clauses, not breaking up parts of one clause."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":166,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0167","version":5,"contentHash":"sha256:7ff3e319c835296a48b112d33de09179d36dd26ab7a4110cdf6c6a00327771b9","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a colon correctly before a list?","choices":["Bring three: supplies pencils, paper, and glue.","Bring three supplies: pencils, paper, and glue.","Bring: three supplies pencils.","Bring three supplies pencils: paper."],"correct":1,"studyAid":{"definition":"A colon is used to introduce a list of items. The words before the colon must form a complete thought or introductory statement.","example":"Correct: I need these items: books, pens, and paper. Incorrect: I need: books, pens, and paper (because 'I need' is not a full list header).","strategyClue":"Look for the spot in the sentence where you could pause to say 'here is the list,' and ensure the words before that pause form a clear introductory statement.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Bring three supplies: pencils, paper, and glue. A colon is used to introduce a list of items after a complete sentence or an introductory phrase.","incorrect":[{"choice":"Bring three: supplies pencils, paper, and glue.","category":"misplaced colon","reason":"The colon must come after the full introductory clause 'Bring three supplies,' not in the middle of a noun phrase."},"",{"choice":"Bring: three supplies pencils.","category":"incorrect colon usage","reason":"You cannot place a colon between a verb ('Bring') and its direct object ('three supplies'), as that breaks the flow of the sentence."},{"choice":"Bring three supplies pencils: paper.","category":"misplaced colon","reason":"The colon should introduce the entire list, not just the last item. It must follow the introductory statement."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":167,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0168","version":5,"contentHash":"sha256:b020fa417b3ac6a8a2fedd1e46dd425e755b6484e920229b1bf8ee55150ea681","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses parentheses correctly?","choices":["The field trip (originally planned for May moved.","The field trip originally) planned for May moved.","The field trip (originally planned for May) moved to June.","The field trip originally planned for May) moved."],"correct":2,"studyAid":{"definition":"Parentheses are punctuation marks used to set off extra information that adds detail to a sentence but is not essential to the main idea.","example":"My dog (a golden retriever) loves to swim. The store closes at 6:00 (or 5:00 on Sundays).","strategyClue":"Look for the extra piece of information that could be removed without changing the main sentence's meaning. Check that an opening mark sits right before the start of that detail and a closing mark sits right after its end.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The field trip (originally planned for May) moved to June. Parentheses must always come in pairs. The information added as extra detail starts with an opening parenthesis and ends with a closing one to properly set off the phrase.","incorrect":[{"choice":"The field trip (originally planned for May moved.","category":"missing closing parenthesis","reason":"This sentence has an opening parenthesis but is missing the closing one at the end of the added information. You must 'close' the set to keep the sentence balanced."},{"choice":"The field trip originally) planned for May moved.","category":"incorrect parenthesis placement","reason":"The closing parenthesis is placed mid-phrase, leaving the opening one out entirely. Parentheses should group a complete extra thought together, not break it into pieces."},"",{"choice":"The field trip originally planned for May) moved.","category":"missing opening parenthesis","reason":"This choice has a closing parenthesis but is missing the opening one at the beginning of the extra detail. Both symbols are required to properly enclose the phrase."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":168,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0169","version":5,"contentHash":"sha256:899f35d9891c7204886e632c7c0446410f38268efd7d64e8f223ed7757ee9838","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a comma after an introductory phrase?","choices":["After the bell, rang students lined up.","After the bell rang students lined up.","After, the bell rang students lined up.","After the bell rang, students lined up."],"correct":3,"studyAid":{"definition":"Use a comma after an introductory phrase or dependent clause to separate it from the main part of the sentence.","example":"Before the game, we practiced hard. (Correct) vs. Before the game we practiced hard. (Incorrect)","strategyClue":"Read the sentence out loud and listen for a natural pause after the introductory group of words; the comma should mark exactly where that pause occurs.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After the bell rang, students lined up. Introductory phrases or clauses set the stage for the main part of the sentence and are followed by a comma to help the reader pause.","incorrect":[{"choice":"After the bell, rang students lined up.","category":"incorrect comma placement","reason":"Placing a comma after 'bell' splits the verb 'rang' from its subject, creating a confusing and incorrect pause in the middle of the phrase."},{"choice":"After the bell rang students lined up.","category":"missing introductory comma","reason":"Without a comma after 'rang', the reader cannot tell where the introductory clause ends and the main sentence begins, which can lead to misreading."},{"choice":"After, the bell rang students lined up.","category":"incorrect comma placement","reason":"Putting a comma after 'After' separates the preposition from the object it describes, which breaks the flow of the sentence."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":169,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0170","version":5,"contentHash":"sha256:f15780661d72f23901d4eff844e650da56d067a322f5abd1878208a7c2dc973a","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a hyphen correctly?","choices":["The well-known author visited our school.","The well known-author visited.","The well known author-visited.","The wellknown author visited."],"correct":0,"studyAid":{"definition":"Use a hyphen to join two words that act as a single adjective before a noun. This helps the reader understand that the two words belong together as one idea.","example":"a high-speed train, a long-term goal, a well-known actor","strategyClue":"Test if the words before the noun are working together by trying to put the word 'and' between them; if 'and' doesn't fit, but the two words describe the noun as a single unit, use a hyphen.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The well-known author visited our school. A hyphen is used to join two words that act as a single adjective before a noun. 'Well-known' describes the author as a unit, so the hyphen connects the two parts correctly.","incorrect":["",{"choice":"The well known-author visited.","category":"misplaced hyphen usage","reason":"Placing the hyphen after 'known' connects it to 'author' instead of 'well'. The hyphen belongs between the two adjectives that modify the noun, not between the adjective and the noun itself."},{"choice":"The well known author-visited.","category":"incorrect compound punctuation","reason":"A hyphen should never connect a noun like 'author' to a verb like 'visited'. The hyphen is meant to link two modifiers that act as one thought before the noun."},{"choice":"The wellknown author visited.","category":"missing necessary hyphen","reason":"'Wellknown' is not a single word in standard English. You must use a hyphen to join two separate words that work together to describe a noun."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":170,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0171","version":5,"contentHash":"sha256:c24486eaaef546512eb3c97d7d27acdec483608b258ba37b2955770c14d345e7","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a dash correctly?","choices":["I opened - the box and gasped at.","I opened the box - and gasped at the surprise inside.","- I opened the box and.","I opened the - box - and."],"correct":1,"studyAid":{"definition":"A dash is a punctuation mark used to add emphasis, show a sudden change in thought, or create a dramatic pause within a sentence.","example":"He ran to the door - but it was locked. I finished the book - finally!","strategyClue":"Read each sentence out loud and look for the spot where a sudden pause or change in thought happens. The dash should act like a bridge or a speed bump at that specific moment of interruption.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: I opened the box - and gasped at the surprise inside. A dash is used to show a sudden break or an interruption in a sentence. In this sentence, the dash correctly emphasizes the pause before the excitement of the surprise.","incorrect":[{"choice":"I opened - the box and gasped at.","category":"incorrect dash placement","reason":"Placing a dash here interrupts the verb 'opened' and its object 'the box'. Dashes should not break apart closely related parts of a sentence like this."},"",{"choice":"- I opened the box and.","category":"improper sentence structure","reason":"Starting a sentence with a dash is grammatically incorrect. Dashes belong in the middle of sentences to connect related thoughts or indicate an interruption."},{"choice":"I opened the - box - and.","category":"excessive punctuation","reason":"Using two dashes like this creates unnecessary clutter. While double dashes can sometimes surround an extra detail, this usage serves no purpose and makes the sentence confusing."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":171,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0172","version":5,"contentHash":"sha256:0d0ba0ebea4e05e88552ac31441a5eaa45d87f503a853b30b0163a7abed82431","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses quotation marks for a title correctly?","choices":["We read \"The Marble Champ in class.","We read The Marble Champ\" in class.","We read \"The Marble Champ\" in class.","We read The Marble Champ in \"class.\""],"correct":2,"studyAid":{"definition":"Use quotation marks around titles of shorter works, such as short stories, poems, songs, or magazine articles. Titles of longer works, like full books or movies, are typically italicized instead.","example":"\"The Road Not Taken\" (poem), \"Twinkle, Twinkle, Little Star\" (song), \"The Marble Champ\" (story)","strategyClue":"Identify the specific name of the work being referenced. Then, place your finger at the very beginning and very end of that specific name to ensure your marks perfectly frame it.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: We read \"The Marble Champ\" in class. Quotation marks must surround the entire title of the short story, starting before the first word and ending after the last word.","incorrect":[{"choice":"We read \"The Marble Champ in class.","category":"missing closing quotation","reason":"This choice starts the quotation but forgets to place the mark at the end of the title 'Champ'. Both ends of a title need a mark."},{"choice":"We read The Marble Champ\" in class.","category":"missing opening quotation","reason":"This choice includes a closing mark but lacks the starting mark. Quotation marks always come in pairs to wrap around the title."},"",{"choice":"We read The Marble Champ in \"class.\"","category":"incorrect title punctuation","reason":"This choice incorrectly marks the word 'class' as the title. The title is the name of the story, not the word describing where you read it."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":172,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0173","version":4,"contentHash":"sha256:a7f715306a4f93b72f9046b22202057e2eafea9ee504a1c6ee681cfd345e93f9","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a colon to show time?","choices":["Practice begins at 4.30.","Practice begins at 4;30.","Practice begins at 4,30.","Practice begins at 4:30."],"correct":3,"studyAid":{"definition":"A colon is a punctuation mark used to show time by separating the hour from the minutes.","example":"6:00, 10:15, 12:45","strategyClue":"When writing time, ask yourself if the mark separates two full sentences or if it acts as a bridge between the hour and the minute digits.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Practice begins at 4:30. In English, a colon is the standard punctuation mark used to separate hours from minutes when writing the time.","incorrect":[{"choice":"Practice begins at 4.30.","category":"incorrect punctuation mark","reason":"Using a period between the 4 and the 30 is incorrect. Periods are used to end sentences or for decimal points, but they do not show time."},{"choice":"Practice begins at 4;30.","category":"misused semicolon","reason":"A semicolon is used to join two independent clauses. It is not the correct mark for separating hours from minutes in time."},{"choice":"Practice begins at 4,30.","category":"misused comma","reason":"A comma is used for lists or pauses in a sentence, not for separating the parts of a time. Using a comma here makes the time difficult to read."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":173,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0174","version":4,"contentHash":"sha256:9b3a0c5c6ccef114cd6cf2d8b3f26cbef2b88b6c2568994f455feee97a36b993","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses commas around a direct address?","choices":["Maya, please pass the markers.","Maya please, pass the markers.","Maya please pass, the markers.","Maya please pass the markers."],"correct":0,"studyAid":{"definition":"A direct address occurs when you speak directly to someone by using their name. You must always use a comma to separate the name from the sentence.","example":"John, come here. / Can you help me, Sarah? / I think, Mom, that we are ready.","strategyClue":"Try saying the sentence out loud and pausing after the person's name. The comma goes exactly where your natural speaking voice takes a short breath.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Maya, please pass the markers. When addressing someone directly by name, you must place a comma between the name and the rest of the sentence to separate the person being spoken to from the command or question.","incorrect":["",{"choice":"Maya please, pass the markers.","category":"misplaced comma","reason":"The comma is placed after 'please,' which breaks the request apart incorrectly. The comma should immediately follow the name of the person being addressed."},{"choice":"Maya please pass, the markers.","category":"unnecessary comma","reason":"Placing a comma between the verb 'pass' and the object 'the markers' interrupts the flow of the sentence. Commas are used to set off names, not to break up action and objects."},{"choice":"Maya please pass the markers.","category":"missing comma","reason":"Without a comma after 'Maya,' the sentence is missing a clear pause. In direct address, the name acts as an introduction and needs punctuation to separate it from the instruction."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":174,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0175","version":5,"contentHash":"sha256:c7bdd1f9e2649cb139c476eb1bec8ac2dfb3670371b20d8d0f590fcbdb139f7b","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a semicolon correctly?","choices":["The storm; ended the teams returned.","The storm ended; the teams returned to the field.","The storm ended; because the field.","The; storm ended."],"correct":1,"studyAid":{"definition":"A semicolon joins two independent, related sentences into one single sentence. Both parts on either side of the semicolon must be able to stand alone as complete thoughts.","example":"I love to read; it is my favorite hobby. The dog barked; we let him inside.","strategyClue":"Cover the semicolon with your finger and check if you have a complete sentence on the left and another complete sentence on the right. If you do not have two full sentences, a semicolon is not the correct choice.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The storm ended; the teams returned to the field. A semicolon is used to join two complete, independent sentences that are closely related in meaning without using a conjunction like 'and' or 'but'.","incorrect":[{"choice":"The storm; ended the teams returned.","category":"semicolon placement error","reason":"Placing a semicolon between the subject 'storm' and the verb 'ended' interrupts the flow of a single clause. Semicolons should connect two whole sentences, not split a single sentence in half."},"",{"choice":"The storm ended; because the field.","category":"conjunction misuse","reason":"A semicolon should connect two independent clauses. The phrase 'because the field' is not a complete sentence, so it cannot follow a semicolon."},{"choice":"The; storm ended.","category":"incorrect punctuation","reason":"The semicolon here is placed between an article and a noun. Never use a semicolon to separate parts of a single phrase or sentence structure."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":175,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0176","version":5,"contentHash":"sha256:cb456d44263150abf3759aa58dc52b84a25148f340986c465feedaaa79c4b5ae","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a colon correctly before a list?","choices":["Bring: three supplies pencils.","Bring three: supplies pencils, paper, and glue.","Bring three supplies: pencils, paper, and glue.","Bring three supplies pencils: paper."],"correct":2,"studyAid":{"definition":"A colon is used to introduce a list of items after a complete independent clause that explains what is coming next.","example":"Correct: We need these ingredients: milk, eggs, and flour. Incorrect: We need: milk, eggs, and flour (the first part is not a complete thought).","strategyClue":"Check if the words before the colon can stand alone as a complete sentence. If they can, and they specifically introduce a series of items, the colon is correctly placed.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Bring three supplies: pencils, paper, and glue. A colon is used to introduce a list after a complete independent clause that introduces the items.","incorrect":[{"choice":"Bring: three supplies pencils.","category":"Incorrect colon placement","reason":"Placing a colon immediately after the verb 'Bring' interrupts the flow of the sentence. The colon must come after the full introduction of the list."},{"choice":"Bring three: supplies pencils, paper, and glue.","category":"Incorrect colon placement","reason":"This places the colon after 'three', which breaks up the noun phrase. The colon should follow the entire introductory thought, not just one word."},"",{"choice":"Bring three supplies pencils: paper.","category":"Incorrect colon placement","reason":"This uses the colon incorrectly between list items rather than introducing the list. A colon must follow a complete sentence or introductory phrase that sets up the list."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":176,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0177","version":5,"contentHash":"sha256:93dfbd779239fb361f0066b4165c8376b2a3cde43638386dac340e8ba242bb09","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses parentheses correctly?","choices":["The field trip originally planned for May) moved.","The field trip originally) planned for May moved.","The field trip (originally planned for May moved.","The field trip (originally planned for May) moved to June."],"correct":3,"studyAid":{"definition":"Parentheses are used to set off non-essential information within a sentence. They always come in pairs—one to open the interruption and one to close it.","example":"My dog (a golden retriever) loves to swim. We visited Paris (the capital of France) last summer.","strategyClue":"Identify the phrase that provides extra detail, then ensure there is a symbol directly before the first word of that phrase and another symbol directly after the last word of that phrase.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The field trip (originally planned for May) moved to June. Parentheses must always work in pairs to enclose extra information that interrupts the flow of a sentence, meaning there must be both an opening '(' and a closing ')' symbol.","incorrect":[{"choice":"The field trip originally planned for May) moved.","category":"missing opening parenthesis","reason":"This sentence has a closing parenthesis but is missing the opening symbol at the start of the extra information. Every pair needs both parts to be complete."},{"choice":"The field trip originally) planned for May moved.","category":"misplaced parentheses","reason":"Parentheses should enclose the entire interrupted phrase. Placing a closing parenthesis in the middle of a phrase makes the sentence difficult to read and grammatically incorrect."},{"choice":"The field trip (originally planned for May moved.","category":"missing closing parenthesis","reason":"This sentence has an opening parenthesis but fails to close it. You must always add a closing symbol after the extra information is finished."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":177,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0178","version":5,"contentHash":"sha256:e1eb8183c8780c4480f8354d43e2f6a867a1fc6d11ad69b1e4f65df106baf75e","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence uses a comma after an introductory phrase?","choices":["After the bell rang, students lined up.","After the bell rang students lined up.","After, the bell rang students lined up.","After the bell, rang students lined up."],"correct":0,"studyAid":{"definition":"A comma is used after an introductory phrase or dependent clause to separate it from the main independent clause.","example":"Running to the store, I saw my friend. / Before the sun came up, we left for the trip.","strategyClue":"Read the sentence out loud and pause naturally at the end of the introductory section. If you find yourself taking a small breath before the main subject of the sentence, that is where the comma belongs.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After the bell rang, students lined up. Introductory phrases or clauses set the stage for the main part of a sentence and should be separated by a comma to help the reader know where the introduction ends and the main idea begins.","incorrect":["",{"choice":"After the bell rang students lined up.","category":"missing introductory comma","reason":"This sentence fails to mark the end of the introductory clause. Without a comma, the reader might momentarily think the bell is ringing the students."},{"choice":"After, the bell rang students lined up.","category":"misplaced comma","reason":"Placing a comma immediately after 'After' interrupts the flow of the phrase. The comma should appear only after the entire introductory clause is complete."},{"choice":"After the bell, rang students lined up.","category":"misplaced comma","reason":"This comma splits the introductory clause in two. Never place a comma between a verb ('rang') and its subject ('students') or inside a short introductory phrase."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":178,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0179","version":7,"contentHash":"sha256:962aa6140f4bdc4a51a5c8702b442178737181c1cb17507643462ee993f36320","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence correctly punctuates dialogue?","choices":["\"Please close the door\" said Omar.","\"Please close the door,\" said Omar.","Please close the door,\" said Omar.","\"Please close the door, said Omar.\""],"correct":1,"studyAid":{"definition":"Dialogue requires quotation marks around the spoken words, and a comma must separate the dialogue from the speech tag (like 'he said' or 'she asked').","example":"\"Hello!\" she shouted. \"I am here,\" he whispered. \"Why?\" they asked.","strategyClue":"Identify the exact words that were spoken aloud and place quotation marks only around that part, then look for the split between the spoken phrase and the speaker's name to place your comma.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: \"Please close the door,\" said Omar. In English dialogue, you must use quotation marks to enclose the spoken words, and place a comma inside the closing quotation mark when the dialogue is followed by a speech tag like 'said Omar'.","incorrect":[{"choice":"\"Please close the door\" said Omar.","category":"missing comma in dialogue","reason":"When a dialogue sentence ends with a speech tag, you must place a comma inside the quotation marks to separate the spoken words from the rest of the sentence."},"",{"choice":"Please close the door,\" said Omar.","category":"missing opening quotation mark","reason":"Dialogue needs quotation marks at both the beginning and the end of the spoken sentence to show exactly what was said."},{"choice":"\"Please close the door, said Omar.\"","category":"incorrect quotation placement","reason":"The speech tag 'said Omar' is not part of the actual spoken words, so it should not be inside the quotation marks."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":179,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}},{"id":"punctuation-advanced-punctuation-q0180","version":7,"contentHash":"sha256:3a11f78c683414f348fa3685558bc9eaae1b191477bf36e3f89291e44e5cfe36","question":"Grade 5 Hard: Analyze the details and choose the strongest answer. Which sentence starts a new speaker correctly?","choices":["\"I found it, said June. Where was it?\" asked Luis.","\"I found it,\" said June. \"Where was it?\" June asked.","\"I found it,\" said June. \"Where was it?\" asked Luis.","I found it, said June. Where was it, asked Luis."],"correct":2,"studyAid":{"definition":"Direct speech requires quotation marks around the spoken words, with punctuation like commas or question marks placed inside the closing quotation mark.","example":"\"Hello,\" said Sam. \"How are you?\" asked Kim.","strategyClue":"Identify the exact words being spoken aloud, put quotes around just those words, and ensure the punctuation mark immediately following the speech stays inside the quote.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: \"I found it,\" said June. \"Where was it?\" asked Luis. Direct speech requires quotation marks around the spoken words, and commas or terminal punctuation must be placed inside those quotation marks.","incorrect":[{"choice":"\"I found it, said June. Where was it?\" asked Luis.","category":"incorrect quotation placement","reason":"The quotation marks are missing after the word 'it'. The spoken words 'I found it' must be enclosed in their own set of quotation marks."},{"choice":"\"I found it,\" said June. \"Where was it?\" June asked.","category":"repetitive subject usage","reason":"While punctuated correctly, this choice is weaker because it identifies the speaker twice unnecessarily. Using a new verb or naming the second speaker once is usually clearer."},"",{"choice":"I found it, said June. Where was it, asked Luis.","category":"missing quotation marks","reason":"This sentence fails to use quotation marks entirely. Direct speech must always be enclosed in quotes to show exactly what was spoken."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["semicolons","colons","parentheses","commas"],"standards":["L.4-6.2"],"feedbackFocus":"check the rule, use the context, and eliminate choices that do not match the whole prompt","estimatedTimeSeconds":85,"reviewPriority":"high","sourceSet":"punctuation-advanced-punctuation","sequence":180,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2","L.4-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["punctuation-advanced-punctuation"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["punctuation-advanced-punctuation"] = chunkSet;
  }
})();
